questions.question:
問題（JavaScript：スコープ）
次のコードの出力として正しいものはどれか。
for (let i = 0; i < 3; i++) {}
console.log(typeof i);

問題（JavaScript：ループとクロージャ）
次のコードの出力として正しいものはどれか。
const fns = [];
for (var i = 0; i < 3; i++) {
  fns.push(() => i);
}
console.log(fns[0](), fns[1](), fns[2]());

問題（JavaScript：デフォルト引数）
次のコードの出力として正しいものはどれか。
function f(x = 10) { return x; }
console.log(f(undefined), f(null));

問題（JavaScript：this の値）
次のコードの出力として正しいものはどれか。（非 strict を想定）
function f() { return this; }
console.log(f() === globalThis);

問題（JavaScript：strict mode の this）
次のコードの出力として正しいものはどれか。
function f() { 'use strict'; return this; }
console.log(f());

問題（JavaScript：短絡評価）
次のコードの出力として正しいものはどれか。
console.log("" && 123);
